      ],
      "observed": "Every VDD supply pin on both MCUs is on an unconnected net.",
      "expected": "Connect the MCU VDD pins to the regulated 3.3 V supply, as required for operation.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (name \"unconnected-(FCC2-VDD-Pad11)\") (node (ref \"FCC2\") (pin \"11\")"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"unconnected-(NAVC2-VDD-Pad19)\") (node (ref \"NAVC2\") (pin \"19\")"
        },
        {
          "source": "spec",
          "quote": "3.3 V LDO (MCUs + sensors)"
        }
      ],
      "impact": "Neither MCU receives power at its VDD pins, so the flight-control and navigation computers cannot operate.",
      "confidence": 1.0
    },
    {
      "category": "open_connection",
      "components": ["REG1", "FCC2", "NAVC2", "U1", "U10", "U14", "U19"],
      "pins": ["REG1.1", "FCC2.11", "NAVC2.19", "U1.4", "U10.3", "U14.28", "U19.9"],
      "nets": ["+3.3V", "+3V3"],
      "observed": "The regulator output and several peripherals are on +3.3V, while a separate +3V3 net feeds MCU decoupling capacitors and connectors. The two nets are not connected in the netlist.",
      "expected": "The 3.3 V regulator output should feed the board's 3.3 V distribution; the differently named nets should be joined if they represent that same rail.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (name \"+3.3V\") ... (node (ref \"REG1\") (pin \"1\") (pinfunction \"OUT\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"+3V3\") ... (node (ref \"C3\") (pin \"1\"))"
        },
        {
          "source": "spec",
          "quote": "From these two regulated rails, 3V3 feeds both MCUs (FCC, NAVC) and all I2C sensor ICs"
        }
      ],
      "impact": "Loads and decoupling tied to +3V3 are isolated from the regulator output, leaving that portion of the board without its intended 3.3 V supply.",
      "confidence": 0.99
    },
    {
      "category": "bridged_nets",
      "components": ["FCC2", "R80", "C12", "C65"],
      "pins": ["FCC2.13", "FCC2.20", "FCC2.21", "R80.1", "R80.2"],
      "nets": ["VREF+_FCC", "VDDA_FCC"],
      "observed": "FCC2.13 (PH1) is connected to VREF+_FCC. R80 connects that net to VDDA_FCC, but the MCU's VREF+ pin FCC2.20 and VDDA pin FCC2.21 are unconnected.",
      "expected": "The analog supply and reference should connect to the MCU's VDDA and VREF+ pins, not to the PH1 GPIO; PH1 should remain on its intended signal net or unconnected.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (name \"VREF+_FCC\") ... (node (ref \"FCC2\") (pin \"13\") (pinfunction \"PH1\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"unconnected-(FCC2-VREF+-Pad20)\")"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"unconnected-(FCC2-VDDA-Pad21)\")"
        }
      ],
      "impact": "The MCU analog supply/reference pins are left open, while the PH1 GPIO is tied into the analog supply/reference network, preventing correct analog operation and potentially affecting that GPIO.",
      "confidence": 0.97
    }
  ],
  "summary": "Anomalies are present: both MCUs have all VDD pins unconnected, the regulator's +3.3V output is isolated from a separate +3V3 net, and the FCC analog supply/reference network is routed to PH1 instead of the MCU's VDDA and VREF+ pins."
}

